@ParameterizedTest
@ValueSource(strings = { "\n", "\r\n", "\r" })
public void singleLine(String lineSeparator) throws Exception {
    CommentRenormalizer commentRenormalizer = new CommentRenormalizer(lexicalHandler, lineSeparator);
    char[] ch = "single line".toCharArray();
    commentRenormalizer.comment(ch, 0, ch.length);
    verify(lexicalHandler).comment(ch, 0, ch.length);
}

@ParameterizedTest
@ValueSource(strings = { "\n", "\r\n", "\r" })
public void multiLine(String lineSeparator) throws Exception {
    CommentRenormalizer commentRenormalizer = new CommentRenormalizer(lexicalHandler, lineSeparator);
    String text = "I%sam%sthe%sbest%s";
    char[] chIn = String.format(text, "\n", "\n", "\n", "\n").toCharArray();
    char[] chOut = String.format(text, lineSeparator, lineSeparator, lineSeparator, lineSeparator).toCharArray();
    commentRenormalizer.comment(chIn, 0, chIn.length);
    verify(lexicalHandler).comment(chOut, 0, chOut.length);
}

@Test
public void testMng5459() throws Exception {
    // prepare
    DefaultArtifactDescriptorReader reader = (DefaultArtifactDescriptorReader) getContainer().lookup(ArtifactDescriptorReader.class);
    RepositoryEventDispatcher eventDispatcher = mock(RepositoryEventDispatcher.class);
    ArgumentCaptor<RepositoryEvent> event = ArgumentCaptor.forClass(RepositoryEvent.class);
    reader.setRepositoryEventDispatcher(eventDispatcher);
    ArtifactDescriptorRequest request = new ArtifactDescriptorRequest();
    request.addRepository(newTestRepository());
    request.setArtifact(new DefaultArtifact("org.apache.maven.its", "dep-mng5459", "jar", "0.4.0-SNAPSHOT"));
    // execute
    reader.readArtifactDescriptor(session, request);
    // verify
    verify(eventDispatcher).dispatch(event.capture());
    boolean missingArtifactDescriptor = false;
    for (RepositoryEvent evt : event.getAllValues()) {
        if (EventType.ARTIFACT_DESCRIPTOR_MISSING.equals(evt.getType())) {
